config.command:
DRY='{{dryRun}}'; REPORT_FILE='/tmp/migration-report-$(date +%Y%m%d-%H%M%S).md'; echo '=== Generating Migration Report ==='; cat > "$REPORT_FILE" << 'EOF'
# Database Migration Report

## Configuration
- **Migration Directory**: {{migrationDir}}
- **SurrealDB URL**: {{surrealUrl}}
- **Namespace**: {{namespace}}
- **Database**: {{database}}
- **Dry Run**: {{dryRun}}

## Files Processed
EOF
cd '{{migrationDir}}' && ls -1 *.surql 2>/dev/null | sort -V >> "$REPORT_FILE" || echo 'None' >> "$REPORT_FILE"; echo '' >> "$REPORT_FILE"; if [ "$DRY" = 'true' ]; then echo '## Status: DRY RUN (no changes made)' >> "$REPORT_FILE"; else echo '## Status: COMPLETED' >> "$REPORT_FILE"; fi; echo '' >> "$REPORT_FILE"; echo "Generated: $(date)" >> "$REPORT_FILE"; echo "Report saved to: $REPORT_FILE"; cat "$REPORT_FILE"
